import { z } from "zod";
import type { DraftState } from "../../models/draft-state.js";
import { resolveApplicablePacks } from "../../packs/resolve-applicable-packs.js";
import { loadSkillDocs } from "../../packs/load-skill-docs.js";
import { DETECT_GAPS_SYSTEM_PROMPT } from "../../prompts/detect-gaps-prompt.js";

export const MissingFactSchema = z.object({
  field: z.string().describe("short machine-usable key, e.g. 'governingLaw', 'phiInvolved', 'sccModule'"),
  question: z.string().describe("the exact question to show the user"),
  severity: z.enum(["critical", "optional"]),
  reasonRequired: z.string().describe("one sentence: why this fact changes what must be drafted"),
  options: z.array(z.string()).optional(),
});

export const ChecklistItemSchema = z.object({
  id: z.string().describe("kebab-case, stable across reruns of the same deal, e.g. 'gdpr-art28-subprocessor-flowdown'"),
  source: z.enum(["documentType", "regime", "jurisdiction"]),
  sourcePackId: z.string().describe("id of the pack this came from, e.g. 'gdpr-art28'"),
  requirement: z.string().describe("one sentence, stated as a testable pass/fail condition — not a summary of the law"),
  severity: z.enum(["critical", "warning"]),
  // Models often paste long skill.md passages; truncate instead of failing the whole draft.
  sourceExcerpt: z
    .string()
    .transform((s) => (s.length > 300 ? `${s.slice(0, 297)}…` : s))
    .describe("the exact sentence(s) in the skill.md this requirement is grounded in (≤300 chars)"),
  sectionTarget: z.string().optional().describe("workUnit id this belongs to, if it maps to one predictable section; omit if cross-cutting"),
});

export const DetectGapsOutputSchema = z.object({
  missingFacts: z.array(MissingFactSchema),
  checklist: z.array(ChecklistItemSchema),
});

export type DetectGapsOutput = z.infer<typeof DetectGapsOutputSchema>;

/** Soft-normalize LLM JSON before Zod so length / enum quirks don't kill the job. */
export function sanitizeDetectGapsRaw(raw: unknown): unknown {
  if (!raw || typeof raw !== "object") return raw;
  const obj = raw as Record<string, unknown>;
  const checklist = Array.isArray(obj.checklist) ? obj.checklist : [];
  return {
    ...obj,
    missingFacts: Array.isArray(obj.missingFacts) ? obj.missingFacts : [],
    checklist: checklist.map((item) => {
      if (!item || typeof item !== "object") return item;
      const row = item as Record<string, unknown>;
      const excerpt =
        typeof row.sourceExcerpt === "string" ? row.sourceExcerpt : String(row.sourceExcerpt ?? "");
      return {
        ...row,
        sourceExcerpt: excerpt.length > 300 ? `${excerpt.slice(0, 297)}…` : excerpt,
      };
    }),
  };
}

export function buildDetectGapsUserMessage(input: {
  facts: Record<string, unknown>;
  draftInstructions: string;
  templateContent?: string | null;
  playbookRules?: { topic: string; rule: string; position?: string; fallbackPosition?: string }[];
  playbookGuidelines?: string;
  skillDocs: { packId: string; packType: "documentType" | "regime" | "jurisdiction"; content: string }[];
  previouslyAskedFields?: string[];
}): string {
  const skillBlock = input.skillDocs
    .map(
      (d) =>
        `--- SKILL DOCUMENT: ${d.packId} (${d.packType}) ---\n${d.content}\n--- END ${d.packId} ---`
    )
    .join("\n\n");

  const templateBlock = input.templateContent?.trim()
    ? `\n\n## Selected / Matched Contract Template (for gap comparison)\n${
        input.templateContent.length > 12_000
          ? `${input.templateContent.slice(0, 12_000)}…`
          : input.templateContent
      }`
    : "";

  const playbookBlock =
    (input.playbookRules && input.playbookRules.length > 0) || input.playbookGuidelines?.trim()
      ? `\n\n## Applicable Playbook Rules & Policy Guidelines (for policy gap comparison)\n${
          input.playbookGuidelines?.trim() ? `Guidelines:\n${input.playbookGuidelines.trim()}\n\n` : ""
        }${
          input.playbookRules?.length
            ? `Playbook Rules:\n${input.playbookRules
                .map(
                  (r) =>
                    `- [${r.topic}] Rule: ${r.rule}${
                      r.position ? ` | Preferred: ${r.position}` : ""
                    }${r.fallbackPosition ? ` | Fallback: ${r.fallbackPosition}` : ""}`
                )
                .join("\n")}`
            : ""
        }`
      : "";

  const previouslyAskedBlock =
    input.previouslyAskedFields && input.previouslyAskedFields.length > 0
      ? `\n\n## Previously Asked / Addressed Fields (DO NOT RE-ASK)\nThe following fields have ALREADY been asked or answered in a previous round: ${input.previouslyAskedFields.join(", ")}.\nDo NOT emit any MissingFact or question for these topics again, regardless of phrasing.`
      : "";

  return `
## Known facts (already extracted — do not re-derive)
${JSON.stringify(input.facts, null, 2)}

## User's drafting instructions (context only)
${input.draftInstructions}
${templateBlock}
${playbookBlock}
${previouslyAskedBlock}

## Applicable skill documents (your primary source of legal compliance rules)
${skillBlock}

Perform a comprehensive gap analysis across ALL available inputs above (User Instructions, Contract Template, Playbook Rules, and Skill Documents).
Identify all missing facts, parameters, variables, bracketed placeholders ([●], [PARTY], [ADDRESS], [GOVERNING LAW], [SLA]), unfilled options, or required policy/compliance parameters that are NOT present in the known facts or user prompt. Emit a critical MissingFact for each missing detail so it can be asked of the user.
Do NOT re-ask or emit MissingFacts for any previously asked or known facts.
`.trim();
}

/** JSON Schema for provider structured output (mirrors DetectGapsOutputSchema). */
export const DETECT_GAPS_JSON_SCHEMA = {
  type: "object",
  properties: {
    missingFacts: {
      type: "array",
      items: {
        type: "object",
        properties: {
          field: { type: "string" },
          question: { type: "string" },
          severity: { type: "string", enum: ["critical", "optional"] },
          reasonRequired: { type: "string" },
          options: { type: "array", items: { type: "string" } },
        },
        required: ["field", "question", "severity", "reasonRequired"],
      },
    },
    checklist: {
      type: "array",
      items: {
        type: "object",
        properties: {
          id: { type: "string" },
          source: {
            type: "string",
            enum: ["documentType", "regime", "jurisdiction"],
          },
          sourcePackId: { type: "string" },
          requirement: { type: "string" },
          severity: { type: "string", enum: ["critical", "warning"] },
          sourceExcerpt: { type: "string" },
          sectionTarget: { type: "string" },
        },
        required: [
          "id",
          "source",
          "sourcePackId",
          "requirement",
          "severity",
          "sourceExcerpt",
        ],
      },
    },
  },
  required: ["missingFacts", "checklist"],
} as const;

export type DetectGapsLlmCall = (
  prompt: string,
  systemInstruction: string,
  jsonSchema: unknown,
  task: string,
  provider?: string
) => Promise<unknown>;

export interface DetectGapsOptions {
  /** Inject for tests; defaults to executeJsonCompletion (lazy-loaded). */
  llmCall?: DetectGapsLlmCall;
}

async function defaultDetectGapsLlmCall(
  prompt: string,
  systemInstruction: string,
  jsonSchema: unknown
): Promise<unknown> {
  // Lazy-load so unit tests can inject llmCall without requiring GOOGLE_CLOUD_PROJECT.
  const { executeJsonCompletion, LLMProvider, LLMTask } = await import(
    "../../../../llm/index.js"
  );
  return executeJsonCompletion(
    prompt,
    systemInstruction,
    jsonSchema,
    LLMTask.DETECT_GAPS,
    LLMProvider.GEMINI
  );
}

async function structuredDetectGapsCall(
  system: string,
  user: string,
  llmCall: DetectGapsLlmCall
): Promise<DetectGapsOutput> {
  const raw = await llmCall(user, system, DETECT_GAPS_JSON_SCHEMA, "DETECT_GAPS", "GEMINI");

  const first = DetectGapsOutputSchema.safeParse(sanitizeDetectGapsRaw(raw));
  if (first.success) return first.data;

  console.warn(
    `[detectGaps] schema issues after sanitize, retrying once: ${JSON.stringify(first.error.issues)}`
  );

  const retryPrompt = `${user}

Previous output failed schema validation:
${JSON.stringify(first.error.issues)}

Return corrected JSON matching the schema exactly. Keep every sourceExcerpt under 300 characters.`;

  const retried = await llmCall(
    retryPrompt,
    system,
    DETECT_GAPS_JSON_SCHEMA,
    "DETECT_GAPS",
    "GEMINI"
  );

  const second = DetectGapsOutputSchema.safeParse(sanitizeDetectGapsRaw(retried));
  if (second.success) return second.data;

  // Last resort: keep whatever checklist/facts we can; never crash the whole draft on excerpt length.
  console.warn(
    `[detectGaps] retry still invalid — returning best-effort empty checklist. issues=${JSON.stringify(second.error.issues)}`
  );
  return { missingFacts: [], checklist: [] };
}

/**
 * PLAN capability — single LLM gap/checklist pass grounded in applicable skill.md files.
 * Returns raw analysis; build-plan freezes it onto state.plan for the deal lifetime.
 */
export async function detectGaps(
  state: DraftState,
  options: DetectGapsOptions = {}
): Promise<DetectGapsOutput> {
  const applicablePacks = resolveApplicablePacks(state);
  const skillDocs = await loadSkillDocs(applicablePacks);
  const llmCall = options.llmCall ?? defaultDetectGapsLlmCall;

  const facts = (state.structuredFacts ?? {}) as Record<string, unknown>;
  console.log(
    `[detectGaps] skillDocs=${skillDocs.length} knownFactKeys=${Object.keys(facts).join(",") || "(none)"}`
  );

  const templateContent = state.retrieval?.matchedTemplate || null;
  const playbookRules = (state.retrieval?.applicablePlaybookRules || []).map((r) => ({
    topic: r.topic,
    rule: r.standardPosition,
    position: r.standardPosition,
    fallbackPosition: r.fallbackPositions?.join("; "),
  }));
  const reqAny = state.request as Record<string, unknown>;
  const playbookGuidelines =
    typeof reqAny.aiRulebookPrompt === "string"
      ? reqAny.aiRulebookPrompt
      : typeof reqAny.playbookGuidelines === "string"
        ? reqAny.playbookGuidelines
        : "";

  const previouslyAskedFields = state.agent?.askedFieldIds ?? [];

  const result = await structuredDetectGapsCall(
    DETECT_GAPS_SYSTEM_PROMPT,
    buildDetectGapsUserMessage({
      facts,
      draftInstructions:
        state.request.rawInstructions ||
        state.requirements?.instructions ||
        "",
      templateContent,
      playbookRules,
      playbookGuidelines,
      skillDocs,
      previouslyAskedFields,
    }),
    llmCall
  );

  console.log(
    `[detectGaps] llm missingFacts=${result.missingFacts.length} critical=${result.missingFacts.filter((f) => f.severity === "critical").length} checklist=${result.checklist.length}`
  );
  return result;
}
