
import { Router, Request, Response } from "express";
import { pool } from "../config/database.js";
import { config } from "../config/index.js";
import authRoutes from "./auth.js";
import adminRoutes from "./admin.js";
import documentRoutes from "./documents.js";
import folderRoutes from "./folders.js";
import libraryItemRoutes from "./libraryItems.js";
import jobRoutes from "./jobs.js"; 
import analyzeRoutes from "./analyze.js";
// import draftingRoutes from "./drafting.js";
import draftingRoutes from "../modules/drafting/api/route.js";
import analysisRoutes from "../modules/analysis/api/route.js";
import compareRoutes from "../modules/compare/api/route.js";
import lawyerRoutes from "./lawyer.js";
import negotiateRoutes from "./negotiate.js";
import vulnerabilitiesRoutes from "./vulnerabilities.js";
import reportRoutes from "./reports.js";
import settingsRoutes from "./settings.js";
import dpaRoutes from "./dpa.js";
import vendorReviewRoutes from "./vendorReview.js";
import aiEthicsRoutes from "./aiEthics.js";
import aiToolsRoutes from "./aiTools.js";
import { authenticateToken } from "../middleware/auth.js";
import { getDocumentParserReadiness } from "../modules/analysis/capabilities/ingest/document-structure/index.js";

const router = Router();

router.get("/health", async (req: Request, res: Response) => {
  if (config.skipDb) {
    return res.json({
      status: "UP",
      database: "SKIPPED",
      documentParser: await getDocumentParserReadiness(),
      timestamp: new Date().toISOString(),
    });
  }

  try {
    const start = Date.now();
    await pool.query("SELECT 1");
    const latency = Date.now() - start;
    res.json({
      status: "UP",
      database: "CONNECTED",
      latency: `${latency}ms`,
      documentParser: await getDocumentParserReadiness(),
      timestamp: new Date().toISOString()
    });
  } catch (err) {
    res.status(503).json({
      status: "DOWN",
      database: "DISCONNECTED",
      documentParser: await getDocumentParserReadiness(),
      timestamp: new Date().toISOString()
    });
  }
});

router.use("/auth", authRoutes);
router.use("/admin", adminRoutes);
router.use("/documents", documentRoutes);
router.use("/folders", folderRoutes);
router.use("/library-items", libraryItemRoutes);
router.use("/jobs", jobRoutes);
router.use("/analyze", analyzeRoutes);

// Refectoring the drafting in drafting folder in modules
// router.use("/drafting", draftingRoutes);
router.use("/drafting", draftingRoutes);
router.use("/analysis", analysisRoutes);
router.use("/compare", compareRoutes);


router.use("/lawyer", lawyerRoutes);
router.use("/negotiate", negotiateRoutes);
router.use("/vulnerabilities", vulnerabilitiesRoutes);
router.use("/reports", reportRoutes);
router.use("/settings", settingsRoutes);
router.use("/dpa", dpaRoutes);
router.use("/vendor-review", vendorReviewRoutes);
router.use("/ai-ethics", aiEthicsRoutes);
router.use("/ai-tools", aiToolsRoutes);

export default router;
